const input = $input.first().json;
const isWebhook = !!input.headers;
const body = isWebhook ? (input.body || {}) : {};

const defaults = {
  source: isWebhook ? 'webhook' : 'schedule',
  industries: body.industry || ['consumer goods', 'food and beverage manufacturing', 'health and human services', 'personal care product manufacturing', 'cosmetics', 'retail apparel and fashion', 'wellness and fitness services'],
  countries: body.country || ['us', 'gb', 'ca', 'au', 'in'],
  company_sizes: body.company_size || ['11-50', '51-200', '201-500'],
  max_businesses: body.size || 30
};

return [{ json: defaults }];

const defaults = $('Set Defaults').first().json;
const existingLeads = $('Fetch Existing Leads').first().json;

const API_KEY = 'YOUR_EXPLORIUM_API_KEY_HERE';

// Build existing company set for dedup
const existingNames = new Set();
const existingDomains = new Set();
for (const r of (existingLeads.records || [])) {
  if (r.fields.company_name) existingNames.add(r.fields.company_name.toLowerCase().trim());
  if (r.fields.website) {
    const domain = r.fields.website.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').toLowerCase();
    existingDomains.add(domain);
  }
}

let businesses = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.explorium.ai/v1/businesses',
    headers: { 'API_KEY': API_KEY, 'Content-Type': 'application/json' },
    body: {
      mode: 'full',
      size: defaults.max_businesses,
      page_size: Math.min(defaults.max_businesses, 100),
      page: 1,
      filters: {
        country_code: { values: defaults.countries },
        company_size: { values: defaults.company_sizes },
        has_website: { value: true },
        linkedin_category: { values: defaults.industries }
      }
    },
    json: true
  });

  const allBiz = resp.data || [];

  // Dedup against existing leads
  businesses = allBiz.filter(b => {
    const name = (b.name || '').toLowerCase().trim();
    const domain = (b.domain || '').toLowerCase().trim();
    if (existingNames.has(name)) return false;
    if (domain && existingDomains.has(domain)) return false;
    return true;
  });
} catch (err) {
  return [{ json: { businesses: [], error: err.message, total: 0 } }];
}

return [{ json: { businesses: businesses.slice(0, 20), total: businesses.length } }];

const data = $input.first().json;
const businesses = data.businesses || [];

if (businesses.length === 0) {
  return [{ json: { prospects: [], businesses: [], count: 0 } }];
}

const API_KEY = 'YOUR_EXPLORIUM_API_KEY_HERE';
const prospects = [];

for (const biz of businesses) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.explorium.ai/v1/prospects',
      headers: { 'API_KEY': API_KEY, 'Content-Type': 'application/json' },
      body: {
        mode: 'full',
        size: 3,
        page_size: 3,
        page: 1,
        filters: {
          business_id: { values: [biz.business_id] },
          job_level: { values: ['founder', 'c-suite', 'cxo', 'vp', 'director', 'owner', 'president'] },
          job_department: { values: ['marketing', 'c-suite', 'sales'] },
          has_email: { value: true }
        }
      },
      json: true
    });

    const found = resp.data || [];
    if (found.length > 0) {
      const best = found[0];
      prospects.push({
        business_id: biz.business_id,
        company_name: biz.name,
        domain: biz.domain,
        website: biz.website || ('https://' + (biz.domain || '')),
        company_description: biz.business_description || '',
        country: biz.country_name || '',
        employees: biz.number_of_employees_range || '',
        revenue: biz.yearly_revenue_range || '',
        prospect_id: best.prospect_id,
        contact_name: best.full_name || (best.first_name + ' ' + best.last_name),
        job_title: best.job_title || '',
        linkedin: best.linkedin || (best.linkedin_url_array || [])[0] || '',
        department: best.job_department_main || '',
        seniority: (best.job_level_main || '').replace(/_/g, ' ')
      });
    }
  } catch (err) {
    // Skip this business on error
  }
}

return [{ json: { prospects, count: prospects.length } }];

const data = $input.first().json;
const prospects = data.prospects || [];
const defaults = $('Set Defaults').first().json;

const records = prospects.map(p => ({
  fields: {
    company_name: p.company_name,
    source: 'vibe5_explorium',
    contact_name: p.contact_name + (p.job_title ? ' (' + p.job_title + ')' : ''),
    email: 'enrichment_pending',
    stage: 'New',
    website: p.website,
    notes: 'Source: Vibe5/Explorium (auto-discovered)\n' +
      'Contact: ' + p.contact_name + '\n' +
      'Title: ' + p.job_title + '\n' +
      'LinkedIn: ' + p.linkedin + '\n' +
      'Department: ' + p.department + '\n' +
      'Seniority: ' + p.seniority + '\n' +
      'Country: ' + p.country + '\n' +
      'Employees: ' + p.employees + '\n' +
      'Revenue: ' + p.revenue + '\n' +
      'Description: ' + (p.company_description || '').substring(0, 300)
  }
}));

// Batch into groups of 10 (Airtable limit)
const batches = [];
for (let i = 0; i < records.length; i += 10) {
  batches.push(records.slice(i, i + 10));
}
const batchBody = { records: batches[0] || [] };

// Build Slack message
let slackMsg = '*:telescope: Vibe5 Prospecting \u2014 ' + prospects.length + ' New Leads Found*\n\n';
slackMsg += 'Source: Explorium API | Industries: ' + defaults.industries.slice(0, 3).join(', ') + '\n';
slackMsg += 'Countries: ' + defaults.countries.join(', ') + ' | Company Size: ' + defaults.company_sizes.join(', ') + '\n\n';

prospects.slice(0, 10).forEach((p, i) => {
  slackMsg += '*' + (i+1) + '. ' + p.company_name + '*';
  if (p.website) slackMsg += ' \u2014 ' + p.website;
  slackMsg += '\n';
  slackMsg += '   Contact: ' + p.contact_name + ' (' + p.job_title + ')\n';
  if (p.linkedin) slackMsg += '   LinkedIn: ' + p.linkedin + '\n';
  slackMsg += '   ' + p.country + ' | ' + p.employees + ' employees | ' + p.revenue + '\n\n';
});

if (prospects.length > 10) {
  slackMsg += '...and ' + (prospects.length - 10) + ' more\n';
}

return [{
  json: {
    batchBody,
    slack_message: slackMsg,
    count: prospects.length,
    prospects
  }
}];

const createResponse = $input.first().json;
const records = createResponse.records || [];

if (records.length === 0) {
  return [{ json: { _skip: true, leads: [], count: 0 } }];
}

const leads = records.map(r => ({
  record_id: r.id,
  company_name: r.fields.company_name || '',
  website: r.fields.website || '',
  industry: '',
  email: r.fields.email || '',
  notes: (r.fields.notes || '').substring(0, 500),
  source: 'vibe5_explorium'
}));

return [{ json: { leads, count: leads.length, _skip: false } }];

const createResponse = $('Create Leads in Airtable').first().json;
const records = createResponse.records || [];

for (const record of records) {
  const fields = record.fields || {};
  try {
    this.helpers.httpRequest({
      method: 'POST',
      url: 'http://n8n-jeet.duckdns.org:5678/webhook/creative-teardown',
      body: {
        lead_id: record.id,
        company_name: fields.company_name || '',
        website: fields.website || '',
        industry: ''
      },
      json: true
    }).catch(() => {});
  } catch(e) {}
}

return [{ json: { triggered: records.length } }];
